function createController(ctx) {
  return {
    loadTree: (sessionId, includeArchived, signal) => loadTree(sessionId, includeArchived, signal),
    openSession: (sessionId) => {
      ctx.uiWorkspace.openSession(sessionId);
    },
    forkAt: async (sessionId, atSeq) => {
      const childId = await ctx.sessions.fork({ sessionId, atSeq, increaseTitle: true });
      ctx.uiWorkspace.openSession(childId);
      return childId;
    },
    archiveBranch: (sessionId, force) => archiveBranch(sessionId, force),
    unarchiveBranch: async (sessionId) => {
      await unarchiveBranch(sessionId);
    },
    saveTree: (tree) => saveTree(tree.currentSessionId),
    downloadTree: async (tree) => {
      const full = tree.includeArchived ? tree : await loadTree(tree.currentSessionId, true);
      downloadTree(full);
    }
  };
}

